 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  const colors = config.intent?.visualSpec?.colors || config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const primitiveRefs = [];
  let loadedTexture = null;

  // Textured plane matching atlas source aspect
  const aspect = 512 / 320;
  const planeHeight = 1.0;
  const planeWidth = planeHeight * aspect;
  const geometry = new ctx.THREE.PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ transparent: true, side: ctx.THREE.DoubleSide });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      const sampled = texture(tex, uv());
      material.colorNode = sampled;
      material.opacityNode = sampled.a;
      material.needsUpdate = true;
    });
  }

  mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render subhead text via font atlas
  for (const item of items) {
    if (!item.text) continue;
    const baseSize = 0.2; // subhead scene-unit token
    const fontSize = item.typography?.fontSize ? (item.typography.fontSize / 42) * baseSize : baseSize;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: colors.paper,
      align: 'center'
    });
    textObj.position.z = 0.08;
    group.add(textObj);
  }

  // Apply any cinematic primitives (empty for this node)
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives[p.name]) {
      primitiveRefs.push(ctx.primitives[p.name](group, p.params));
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    primitiveRefs.forEach((p) => p?.cleanup?.());
    loadedTexture?.dispose?.();
    geometry.dispose();
    material.dispose();
  };

  return group;
}
